join public.invoices i on i.number = v.numero
 and i.notes like 'Importata dall''archivio ENTRATE%'
where not exists (
  select 1 from public.invoice_righe r where r.invoice_id = i.id and r.ordine = v.ordine
);

select
  (select count(*) from public.invoice_righe) as righe_totali,
  (select count(distinct invoice_id) from public.invoice_righe) as fatture_con_righe,
  (select count(*) from public.invoices i
    where i.notes like 'Importata%'
      and abs(i.total - coalesce((select sum(r.importo) from public.invoice_righe r where r.invoice_id = i.id), 0) - i.vat_amount) > 0.02
  ) as totali_che_non_quadrano;
